{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '이야기해야 할 것'이라는 말에 거슬림을 느끼고 '남이 정해주는 느낌'이라고 표현한 것은, 자신이 특별한 사람이므로 보통 사람에게 적용되는 규칙(여기서: 상담에서 무엇을 이야기할지 정해지는 것)이 자신에게 적용되어서는 안 된다는 핵심 신념과 직접 연결됨. 성장 배경에서 어머니가 '다른 애들과는 급이 다르다'고 반복한 경험이 이 신념의 근원."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '남이 정해주는 느낌'이라고 표현한 것은 '능력도 없는 사람들이 나에게 이래라저래라 하는 것은 참을 수 없는 일'이라는 태도와 정확히 일치. 인사팀장이 상담을 '통보'한 상황(상황 사례 0)에서도 같은 태도가 분노와 모욕감으로 표출된 바 있음."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data"],
      "relevance": "상담이라는 구조 자체가 '남이 정해주는' 상황을 만들며, 이는 '보통 사람들과 같은 취급을 받으면 그저 그런 사람으로 전락한다'는 부정적 가정과 충돌. 내담자가 '여기서 이야기하고 싶은 건 없습니다'라고 단정하는 것은, 이 자리에 스스로를 '일반인처럼' 놓는 것을 회피하려는 움직임으로 해석 가능."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '인사팀에서 나오라고 해서 온 거고요', '여기서 이야기하고 싶은 건 없습니다'라고 한 것은, 통제할 수 없는 자리(상담)를 형식적으로 임하거나 깎아내리는 대처 방식의 초기 발현. 상담사가 선택지를 제시하며 통제감을 돌려주려는 시도는 이 대처 방식을 우회하려는 시도."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": [],
      "relevance": "'내 판단이 기준이 되어야 한다'는 규칙이 '남이 정해주는 느낌'에 대한 거슬림의 근거가 됨. 상담사가 '직접 정해보시면 어떨까요'라고 한 것은 이 규칙을 존중하면서도 상담 관계에 참여하도록 유도하는 개입."
    }
  ]
}

